/* ---------------------------------------------------------------- webs home */
function miniWeb(w) { const P = layoutOf({ ...w, layout: 'circle', pos: {} }); const ids = w.members.filter(entVisible); const R = visRels().filter((r) => ids.includes(r.a) && ids.includes(r.b)); return `<svg viewBox="0 0 ${GW} ${GH}" class="somini" aria-hidden="true">${R.map((r) => `<line x1="${P[r.a][0]}" y1="${P[r.a][1]}" x2="${P[r.b][0]}" y2="${P[r.b][1]}"/>`).join('')}${ids.map((i) => `<circle cx="${P[i][0]}" cy="${P[i][1]}" r="14"/>`).join('')}</svg>`; }
