/* ---------------------------------------------------------------- types and standings (authors) and problems (staff) */
function pTypes() {
  if (!isGM()) return `<div class="page page--wide page-enter so"><div class="soempty"><p><b>This page does not exist.</b></p><a class="btn" href="#/webs">Back to the webs</a></div></div>`;
  const tree = (p, d) => TYPES.filter((t) => (t.parent || null) === p).map((t) => `<li style="padding-left:${d * 20}px"><div class="sotype"><span class="solink2">${esc(t.n)}</span><span class="t-meta">${t.reads ? `${t.directed ? 'one-way' : 'two-way'} · “A ${esc(t.reads)} B”${t.back ? ` · from the other end “${esc(t.back)}”` : ''}` : 'a group of types'}</span><button type="button" class="btn sm ghost" data-so="edittype" data-v="${t.id}">Edit</button></div></li>${tree(t.id, d + 1)}`).join('');
  return `<div class="page page--capped page-enter so"><div class="head-row"><div class="grow"><h1 class="t-title page-title">Types and standings</h1><p class="page-sub">The words of ${esc(lib())}: what a relationship can be, and what can be measured.</p></div></div>
  ${SC.noTypes ? `<div class="soempty">${slot('empty-social-types', 'No types yet')}<p><b>No relationship types in this library yet.</b></p><p class="t-meta">Start from the ready-made ones, or write your own.</p><div class="soacts"><button type="button" class="btn btn--primary" data-so="starter">Start from the ready-made types</button><button type="button" class="btn" data-so="newtype">${ic('add')}<span>Write a type</span></button></div></div>` : `<section class="sosec2"><div class="sh"><h2 class="t-sec">Types</h2><button type="button" class="btn sm" data-so="newtype">${ic('add')}<span>New type</span></button></div><ul class="sotree">${tree(null, 0)}</ul></section>
  <section class="sosec2"><div class="sh"><h2 class="t-sec">Standings</h2><button type="button" class="btn sm" data-so="newstanding">${ic('add')}<span>New standing</span></button></div><table class="sotbl"><thead><tr><th scope="col">Standing</th><th scope="col">Minimum</th><th scope="col">Maximum</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>${STANDINGS.map((s) => `<tr><th scope="row">${esc(s.n)}</th><td class="num">${s.min !== null ? s.min : '—'}</td><td class="num">${s.max !== null ? s.max : '—'}</td><td><button type="button" class="btn sm ghost" data-so="editstanding" data-v="${s.id}">Edit scale</button></td></tr>`).join('')}</tbody></table></section>
  <section class="sosec2"><h2 class="t-sec">How a type reads</h2><p class="t-meta">Three optional stats on a type say whether it is one-way and how it reads from each end. The library says which stat definitions they are; without them a relationship reads with its type's name.</p><dl class="sodl wide"><div><dt>Directed</dt><dd>Stat “Directed”</dd></div><div><dt>Reads as</dt><dd>Stat “Reads as”</dd></div><div><dt>Reads as, from the other end</dt><dd>Stat “Reads as, from the other end”</dd></div></dl></section>`}</div>`;
}
function problems() {
  const out = []; const R = RELS.filter(relVisible); const cells = {};
  R.forEach((r) => { const k = twoWay(r) ? [r.a, r.b].sort().join('|') : r.a + '>' + r.b; (cells[k + '|' + r.type] = cells[k + '|' + r.type] || []).push(r); });
  Object.values(cells).filter((L) => L.length > 1).forEach((L) => out.push({ kind: 'Doubled', text: `Two relationships of one type for one pair: ${L.map(sentence).join(' and ')}`, ids: L.map((r) => r.id) }));
  R.filter((r) => r.through.length).forEach((r) => { const L = r.through.map(relOf).filter(Boolean); const ends = new Set(); L.forEach((x) => { ends.add(x.a); ends.add(x.b); }); const meet = ends.has(r.a) && ends.has(r.b) && L.every((x, i) => i === 0 || [x.a, x.b].some((e) => [L[i - 1].a, L[i - 1].b].includes(e))); if (!meet) out.push({ kind: 'Chain', text: `${sentence(r)} is stated through a chain whose ends do not meet`, ids: [r.id] }); });
  R.forEach((r) => { if (r.type === 'member' && GROUP_MEMBERS[r.b] && !GROUP_MEMBERS[r.b].includes(r.a)) out.push({ kind: 'Group', text: `${sentence(r)}, but ${entName(r.a)} is not a member of ${entName(r.b)}`, ids: [r.id] }); });
  return out;
}
function pProblems() {
  if (!isGM()) return `<div class="page page--wide page-enter so"><div class="soempty"><p><b>This page does not exist.</b></p><a class="btn" href="#/webs">Back to the webs</a></div></div>`;
  const P = problems();
  return `<div class="page page--capped page-enter so"><div class="head-row"><div class="grow"><h1 class="t-title page-title">Problems</h1><p class="page-sub">Things that look wrong in ${esc(lib())}, for staff.</p></div></div>${P.length ? `<ul class="solist sofull">${P.map((p) => `<li><span class="aud">${p.kind}</span><span>${esc(p.text)}</span>${p.ids.map((id) => `<a href="#/rel/${id}">Open</a>`).join(' ')}</li>`).join('')}</ul>` : '<div class="soempty"><p><b>No problems.</b></p><p class="t-meta">Doubled relationships, chains that do not meet and groups that disagree show up here.</p></div>'}</div>`;
}
